import * as THREE from 'three';
import { scene } from '../../core/renderer';
import { CONFIG } from '../../config';
import { buildAtlas, type Atlas } from './adAtlas';
import { clearRects, collectBuildings, snapshot, type Rect } from './clearance';
import { buildLandmarks, type Landmarks } from './landmarks';
import { buildHearts, type Hearts } from './heartFacade';
import { buildBillboards, panoRects, type Billboards } from './billboards';
import { buildPromenade, type Promenade } from './promenade';

/* [riverfront] Hai bờ sông Hàn: địa danh thật, mặt dựng LED trái tim + "DN", bảng quảng cáo, chi tiết bờ.
   Gọi buildRiverfront() SAU mọi lệnh dựng có dùng rand() (sau HanTunnel trong main.ts): chỉ thu nhỏ instance nhà/cây bị đè về 0. */
export interface Riverfront {
  group: THREE.Group; atlas: Atlas; landmarks: Landmarks; hearts: Hearts; billboards: Billboards; promenade: Promenade;
  footprints: Rect[]; cleared: { buildings: number; plants: number }; snapshot: typeof snapshot;
  adsEnabled: boolean;
}
let current: Riverfront | null = null;
export const getRiverfront = () => current;

export function buildRiverfront(): Riverfront {
  const group = new THREE.Group(); group.name = 'riverfront';
  const atlas = buildAtlas(), landmarks = buildLandmarks();
  const footprints = [...landmarks.rects, ...panoRects()];
  const cleared = clearRects(footprints, CONFIG.riverfront.clearMargin);
  const buildings = collectBuildings();                    // nhà còn lại sau khi dọn: chọn mái, mặt tiền, cửa hàng từ đây
  const hearts = buildHearts(landmarks.towers);
  const billboards = buildBillboards(atlas, landmarks, buildings);
  const promenade = buildPromenade(atlas, billboards.adMat, buildings);
  group.add(landmarks.mesh, hearts.mesh, billboards.group, promenade.group);
  scene.add(group);
  current = { group, atlas, landmarks, hearts, billboards, promenade, footprints, cleared, snapshot, adsEnabled: true };
  return current;
}
export function updateRiverfront(dt: number, _time: number) {
  if (!current) return;
  current.hearts.update(dt);
  if (current.adsEnabled) { current.billboards.update(dt); current.promenade.update(); }
}
export function setHeartsEnabled(on: boolean) { current?.hearts.setEnabled(on); }
export function setHeartsMode(m: 'duet' | 'sync') { current?.hearts.setMode(m); }
/* "Quảng cáo": bảng quảng cáo + băng rôn + bảng hiệu; không tắt chi tiết bờ (lan can, ghế…) */
export function setAdsEnabled(on: boolean) { if (!current) return; adsWanted = on; applyAds(); }
/* Thời tiết (bão) tắt quảng cáo tạm thời; hết bão trả đúng lựa chọn của người dùng (adsWanted), không ép bật */
export function setAdsSuppressed(on: boolean) { adsSuppressed = on; applyAds(); }
let adsWanted = true, adsSuppressed = false;
function applyAds() { if (!current) return; const on = adsWanted && !adsSuppressed; if (current.adsEnabled === on) return; current.adsEnabled = on; current.billboards.setEnabled(on); }
export function disposeRiverfront() {
  if (!current) return;
  const c = current; c.hearts.dispose(); c.billboards.dispose(); c.promenade.dispose(); c.atlas.dispose();
  c.landmarks.mesh.geometry.dispose(); (c.landmarks.mesh.material as THREE.Material).dispose(); c.group.removeFromParent(); current = null;
}
import * as THREE from 'three';
import { scene } from '../../core/renderer';
import { MAT } from '../../core/materials';

/* [clearance] Dọn nhà, cây, cột đèn ngẫu nhiên đè lên công trình mới mà KHÔNG đụng tới chuỗi rand() của khu phố:
   sau khi cảnh đã dựng, gán ma trận scale 0 cho instance bị đè (cả level near lẫn far của LOD nhà), giống corridor.ts của hầm. */
export interface Rect { x0: number; x1: number; z0: number; z1: number }
export interface Building { mesh: THREE.InstancedMesh; i: number; x: number; z: number; w: number; d: number; h: number }

const plants = () => new Set<THREE.Material>([MAT.trunk, MAT.leaf, MAT.palm, MAT.lampPole, MAT.bulb]);
const _m = new THREE.Matrix4(), _p = new THREE.Vector3(), _q = new THREE.Quaternion(), _s = new THREE.Vector3(), _zero = new THREE.Matrix4().makeScale(0, 0, 0);

/* Các InstancedMesh nhà (con của THREE.LOD do buildCity dựng); level 0 là bản gần có cửa sổ */
function buildingMeshes() {
  const out: { mesh: THREE.InstancedMesh; near: boolean }[] = [];
  scene.traverse((o) => {
    const m = o as THREE.InstancedMesh;
    if (m.isInstancedMesh && m.parent && (m.parent as THREE.LOD).isLOD) out.push({ mesh: m, near: (m.parent as THREE.LOD).levels[0]?.object === m });
  });
  return out;
}
/* Nhà đang hiện (scale > 0) ở level near, tọa độ thế giới */
export function collectBuildings(): Building[] {
  scene.updateMatrixWorld(true);
  const list: Building[] = [];
  for (const { mesh, near } of buildingMeshes()) {
    if (!near) continue;
    for (let i = 0; i < mesh.count; i++) {
      mesh.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
      if (_s.x < 1e-6) continue;
      _p.applyMatrix4(mesh.matrixWorld);
      list.push({ mesh, i, x: _p.x, z: _p.z, w: _s.x, d: _s.z, h: _s.y });
    }
  }
  return list;
}
/* Ảnh chụp ma trận nhà ngay trước khi dọn, để kiểm tra "nhà không bị dọn giữ nguyên ma trận" */
export const snapshot = new Map<THREE.InstancedMesh, Float32Array>();

export function clearRects(rects: Rect[], margin: number) {
  scene.updateMatrixWorld(true);
  const pl = plants(); let nb = 0, np = 0;
  const hit = (x: number, z: number, hw: number, hd: number) => rects.some((r) => x + hw > r.x0 - margin && x - hw < r.x1 + margin && z + hd > r.z0 - margin && z - hd < r.z1 + margin);
  scene.traverse((obj) => {
    const o = obj as THREE.InstancedMesh;
    if (!o.isInstancedMesh) return;
    const building = !!o.parent && (o.parent as THREE.LOD).isLOD;
    if (!building && !pl.has(o.material as THREE.Material)) return;
    if (building && !snapshot.has(o)) snapshot.set(o, (o.instanceMatrix.array as Float32Array).slice());
    let changed = false;
    for (let i = 0; i < o.count; i++) {
      o.getMatrixAt(i, _m); _m.decompose(_p, _q, _s);
      if (_s.x < 1e-6) continue;
      _p.applyMatrix4(o.matrixWorld);
      if (hit(_p.x, _p.z, building ? _s.x / 2 : 1.5, building ? _s.z / 2 : 1.5)) { o.setMatrixAt(i, _zero); changed = true; building ? nb++ : np++; }
    }
    if (changed) o.instanceMatrix.needsUpdate = true;
  });
  return { buildings: nb, plants: np };
}
import { setHeartsEnabled, setHeartsMode, setAdsEnabled } from '../environment/riverfront';
import type { Toggle } from './panel';

/* Hai bờ sông Hàn: bật/tắt đèn trái tim, chọn Đối đáp / Đồng bộ, bật/tắt quảng cáo */
export function setupRiverfrontUI(toggle: Toggle) {
  toggle('btnRfHearts', (on) => setHeartsEnabled(on));
  toggle('btnRfAds', (on) => setAdsEnabled(on));
  document.getElementById('rfHeartsMode').addEventListener('change', (e) => setHeartsMode((e.target as HTMLSelectElement).value as 'duet' | 'sync'));
}
  // Cầu Tình Yêu: cầu tàu nhô ra từ kè Đông, cọc, lan can, khóa tình yêu, bệ + tượng cá chép hóa rồng ở đầu cầu
  const L = R.love, x1 = CONFIG.bankX, x0 = x1 - L.length, xm = (x0 + x1) / 2;
